    using WAKINT = ftl::mmio::Field<1, 0, eWAKINT, ftl::mmio::RW, ftl::mmio::OneToClear>;
    // Error Interrupt
    using ERRINT = ftl::mmio::Field<1, 1, eERRINT, ftl::mmio::RW, ftl::mmio::OneToClear>;
    // Bus Off Interrupt
    using BOFFINT = ftl::mmio::Field<1, 2, eBOFFINT, ftl::mmio::RW, ftl::mmio::OneToClear>;
    // FlexCAN In Reception
