    // Fault Confinement State
    using FLTCONF = ftl::mmio::Field<2, 4, eFLTCONF, ftl::mmio::RO, ftl::mmio::Normal>;
    // FlexCAN In Transmission
    using TX = ftl::mmio::Field<1, 6, eTX, ftl::mmio::RO, ftl::mmio::Normal>;
    // IDLE
    using IDLE = ftl::mmio::Field<1, 7, eIDLE, ftl::mmio::RO, ftl::mmio::Normal>;
