    // TX Error Warning
    using TXWRN = ftl::mmio::Field<1, 9, eTXWRN, ftl::mmio::RO, ftl::mmio::Normal>;
    // Stuffing Error
    using STFERR = ftl::mmio::Field<1, 10, eSTFERR, ftl::mmio::RO, ftl::mmio::Normal>;
    // Form Error
    using FRMERR = ftl::mmio::Field<1, 11, eFRMERR, ftl::mmio::RO, ftl::mmio::Normal>;
    // Cyclic Redundancy Check Error
    using CRCERR = ftl::mmio::Field<1, 12, eCRCERR, ftl::mmio::RO, ftl::mmio::Normal>;
    // Acknowledge Error
    using ACKERR = ftl::mmio::Field<1, 13, eACKERR, ftl::mmio::RO, ftl::mmio::Normal>;
    // Bit0 Error
    using BIT0ERR = ftl::mmio::Field<1, 14, eBIT0ERR, ftl::mmio::RO, ftl::mmio::Normal>;
    // Bit1 Error
    using BIT1ERR = ftl::mmio::Field<1, 15, eBIT1ERR, ftl::mmio::RO, ftl::mmio::Normal>;
    // Rx Warning Interrupt Flag
    using RWRNINT = ftl::mmio::Field<1, 16, eRWRNINT, ftl::mmio::RW, ftl::mmio::OneToClear>;
    // Tx Warning Interrupt Flag
    using TWRNINT = ftl::mmio::Field<1, 17, eTWRNINT, ftl::mmio::RW, ftl::mmio::OneToClear>;
    // CAN Synchronization Status
    using SYNCH = ftl::mmio::Field<1, 18, eSYNCH, ftl::mmio::RO, ftl::mmio::Normal>;
    // Bus Off Done Interrupt
    using BOFFDONEINT = ftl::mmio::Field<1, 19, eBOFFDONEINT, ftl::mmio::RW, ftl::mmio::OneToClear>;
    // Error interrupt for errors detected in Data Phase of CAN FD frames with BRS bit set
    using ERRINT_FAST = ftl::mmio::Field<1, 20, eERRINT_FAST, ftl::mmio::RW, ftl::mmio::OneToClear>;
    // Error Overrun
    using ERROVR = ftl::mmio::Field<1, 21, eERROVR, ftl::mmio::RW, ftl::mmio::OneToClear>;
    // Stuffing Error in the Data Phase of CAN FD frames with the BRS bit set
    using STFERR_FAST = ftl::mmio::Field<1, 26, eSTFERR_FAST, ftl::mmio::RO, ftl::mmio::Normal>;
    // Form Error in the Data Phase of CAN FD frames with the BRS bit set
    using FRMERR_FAST = ftl::mmio::Field<1, 27, eFRMERR_FAST, ftl::mmio::RO, ftl::mmio::Normal>;
    // Cyclic Redundancy Check Error in the CRC field of CAN FD frames with the BRS bit set
    using CRCERR_FAST = ftl::mmio::Field<1, 28, eCRCERR_FAST, ftl::mmio::RO, ftl::mmio::Normal>;
    // Bit0 Error in the Data Phase of CAN FD frames with the BRS bit set
    using BIT0ERR_FAST = ftl::mmio::Field<1, 30, eBIT0ERR_FAST, ftl::mmio::RO, ftl::mmio::Normal>;
    // Bit1 Error in the Data Phase of CAN FD frames with the BRS bit set
    using BIT1ERR_FAST = ftl::mmio::Field<1, 31, eBIT1ERR_FAST, ftl::mmio::RO, ftl::mmio::Normal>;
