  // Memory Error Control Register
  struct MECR_fields_ {
    enum class eNCEFAFRZ : std::uint32_t {
      // Keep normal operation.
      enormal = 0,
      // Put FlexCAN in Freeze mode (see section "Freeze mode").
      efreeze = 1,
    };

    enum class eECCDIS : std::uint32_t {
      // Enable memory error correction.
      eENABLE = 0,
      // Disable memory error correction.
      eDISABLE = 1,
    };

    enum class eRERRDIS : std::uint32_t {
      // Enable updates of the error report registers.
      eENABLE = 0,
      // Disable updates of the error report registers.
      eDISABLE = 1,
    };

    enum class eEXTERRIE : std::uint32_t {
      // Error injection is applied only to the 32-bit word.
      einject_32_bit = 0,
      // Error injection is applied to the 64-bit word.
      einject_64_bit = 1,
    };

    enum class eFAERRIE : std::uint32_t {
      // Injection is disabled.
      eDISABLE = 0,
      // Injection is enabled.
      eENABLE = 1,
    };

    enum class eHAERRIE : std::uint32_t {
      // Injection is disabled.
      eDISABLE = 0,
      // Injection is enabled.
      eENABLE = 1,
    };

    enum class eCEI_MSK : std::uint32_t {
      // Interrupt is disabled.
      eDISABLE = 0,
      // Interrupt is enabled.
      eENABLE = 1,
    };

    enum class eFANCEI_MSK : std::uint32_t {
      // Interrupt is disabled.
      eDISABLE = 0,
      // Interrupt is enabled.
      eENABLE = 1,
    };

    enum class eHANCEI_MSK : std::uint32_t {
      // Interrupt is disabled.
      eDISABLE = 0,
      // Interrupt is enabled.
      eENABLE = 1,
    };

    enum class eECRWRDIS : std::uint32_t {
      // Write is enabled.
      eENABLE = 0,
      // Write is disabled.
      eDISABLE = 1,
    };

    // Non-Correctable Errors In FlexCAN Access Put Device In Freeze Mode
    using NCEFAFRZ = ftl::mmio::Field<1, 7, eNCEFAFRZ, ftl::mmio::RW, ftl::mmio::Normal>;
    // Error Correction Disable
    using ECCDIS = ftl::mmio::Field<1, 8, eECCDIS, ftl::mmio::RW, ftl::mmio::Normal>;
    // Error Report Disable
    using RERRDIS = ftl::mmio::Field<1, 9, eRERRDIS, ftl::mmio::RW, ftl::mmio::Normal>;
    // Extended Error Injection Enable
    using EXTERRIE = ftl::mmio::Field<1, 13, eEXTERRIE, ftl::mmio::RW, ftl::mmio::Normal>;
    // FlexCAN Access Error Injection Enable
    using FAERRIE = ftl::mmio::Field<1, 14, eFAERRIE, ftl::mmio::RW, ftl::mmio::Normal>;
    // Host Access Error Injection Enable
    using HAERRIE = ftl::mmio::Field<1, 15, eHAERRIE, ftl::mmio::RW, ftl::mmio::Normal>;
    // Correctable Errors Interrupt Mask
    using CEI_MSK = ftl::mmio::Field<1, 16, eCEI_MSK, ftl::mmio::RW, ftl::mmio::Normal>;
    // FlexCAN Access With Non-Correctable Errors Interrupt Mask
    using FANCEI_MSK = ftl::mmio::Field<1, 18, eFANCEI_MSK, ftl::mmio::RW, ftl::mmio::Normal>;
    // Host Access With Non-Correctable Errors Interrupt Mask
    using HANCEI_MSK = ftl::mmio::Field<1, 19, eHANCEI_MSK, ftl::mmio::RW, ftl::mmio::Normal>;
    // Error Configuration Register Write Disable
    using ECRWRDIS = ftl::mmio::Field<1, 31, eECRWRDIS, ftl::mmio::RW, ftl::mmio::Normal>;
  };  // struct MECR_fields_

